import{_ as l,l as r,o as t,c as o,v as e,p as h,x as i,d as c,i as p,S as s}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Activation Patching 激活修补","description":"","frontmatter":{"title":"Activation Patching 激活修补","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/activation-patching.md","filePath":"llm/activation-patching.md","lastUpdated":1789023840000}'),m={name:"llm/activation-patching.md"};function d(E,a,_,g,A,P){const n=r("Mermaid");return t(),o("div",null,[a[1]||(a[1]=e('<h1 id="activation-patching-激活修补" tabindex="-1">Activation Patching 激活修补 <a class="header-anchor" href="#activation-patching-激活修补" aria-label="Permalink to &quot;Activation Patching 激活修补&quot;">​</a></h1><div class="epigraph"><p>我们设计一种因果干预，用来找出对模型事实预测起决定作用的神经元激活，并显示中间层前馈模块在处理主语 token 时介导了事实回忆。</p><footer>—— Meng et al., Locating and Editing Factual Associations in GPT, NeurIPS 2022</footer></div><p>激活修补（activation patching）是把一次前向里的激活，换成另一次前向里对应位置的激活，看输出如何变。它问的是因果介导，不是相关。Meng 等人在 ROME 论文里称之为因果追踪（causal tracing）：在干净运行与损坏运行之间，把隐藏状态按层、按 token 逐块贴回去，定位事实回忆发生在哪。Wang 等人在 IOI 电路工作里用同类干预还原 GPT-2 small 的间接宾语识别。Nanda、Heimersheim、Zhang 等人后来整理了度量与最佳实践。本篇写协议、度量、以及它不能推出的结论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>消融一个头、看准确率下降，只能说明该头「有贡献」，说不清贡献的是信息本身还是破坏了无关通路。梯度归因给出敏感度，不是反事实。要回答「这个激活是否携带了使输出从错误变正确的信息」，需要一次对换：在失败的前向里，注入成功前向的激活，输出是否修复。</p><p>修补的最小单元可以是一层残差、一个注意力头输出、MLP 输出、甚至单个神经元。单元越细，定位越准，组合爆炸越严重。协议必须先规定干净输入、损坏输入、以及成功的操作定义（正确 token 的 logit 差、准确率、或 KL）。</p><h3 id="干净、损坏与修复" tabindex="-1">干净、损坏与修复 <a class="header-anchor" href="#干净、损坏与修复" aria-label="Permalink to &quot;干净、损坏与修复&quot;">​</a></h3><p>典型三元组：干净提示 \\(x_{\\mathrm{clean}}\\) 模型答对；损坏提示 \\(x_{\\mathrm{corr}}\\)（改主语、打乱人名、切掉关键句）模型答错；修补则在 \\(x_{\\mathrm{corr}}\\) 的前向中，把指定位置的激活换成 \\(x_{\\mathrm{clean}}\\) 同位置的激活。若修复度量显著上升，该位置介导了干净运行里的关键信息。反向修补（在干净运行中贴入损坏激活）测量必要性：贴入后是否变糟。</p><p><span class="marginnote">Meng 的因果追踪常用高斯噪声破坏主语嵌入，再看哪一层把干净激活贴回去能恢复「宾语」预测。这与改写提示文本的损坏不同。噪声损坏假设「损坏 = 看不清主语」；改名损坏假设「损坏 = 主语换成别人」。两种损坏定位到的层可以不同，必须在论文里写死。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记 \\(h^{\\ell,t}(x)\\) 为输入 \\(x\\) 在层 \\(\\ell\\)、位置 \\(t\\) 的激活。修补前向计算</p> \\[h^{\\ell,t}(x_{\\mathrm{corr}}) \\leftarrow h^{\\ell,t}(x_{\\mathrm{clean}}), \\]<p>其余仍按 \\(x_{\\mathrm{corr}}\\) 走。度量常用 logit difference：正确续写 token 减对照 token 的 logit。Zhang 与 Nanda（ICLR 2024）比较了多种度量，指出归一化方式会改变「哪一层看起来最重要」，并建议报告完整的修复曲线，而不是只报峰值层。</p><h3 id="路径修补与冻结" tabindex="-1">路径修补与冻结 <a class="header-anchor" href="#路径修补与冻结" aria-label="Permalink to &quot;路径修补与冻结&quot;">​</a></h3><p>普通修补把某个张量整块替换，信息仍可从该张量的下游与旁路同时走。路径修补（path patching）进一步冻结其余节点，只允许指定边把差异送下去，用来画电路里的边。IOI 工作依赖这类精细干预，才把「哪些头读哪些头」从相关做成因果。代价是实现复杂、且冻结假设可能人为切断真实并行通路。</p><p>Heimersheim 与 Nanda 的教程强调：先做残差流的粗修补定层与 token，再在候选层里头级、MLP 级细分。一上来就扫所有头，多重比较会制造假阳性。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>修补能修复输出，说明被替换的激活对下游是充分的信息源之一：下游计算会读它。它不说明这是唯一源。并行电路很常见——修补 A 能修复，修补 B 也能修复，消融 A 却几乎无事，因为 B 顶上。充分性与必要性必须成对做。</p><h3 id="事实定位为何落在中层-mlp" tabindex="-1">事实定位为何落在中层 MLP <a class="header-anchor" href="#事实定位为何落在中层-mlp" aria-label="Permalink to &quot;事实定位为何落在中层 MLP&quot;">​</a></h3><p>Meng 等人发现，对「主语–关系–宾语」型事实，修复峰值常出现在中层 MLP、且在主语最后一个 token 上。解释是：MLP 作为键值记忆，在主语位置写入属性；之后注意力把属性拷到句末再解嵌。ROME 用这一因果定位去做秩一权重编辑。定位依赖于损坏方式与模板；换一种关系，峰值层会漂移。激活修补在这里的角色是「找到编辑该动手的计算位点」，不是「证明记忆只存在于这一层」。</p><p><span class="marginnote">修补替换的是激活，不是权重。它告诉你这一次前向的介导位点，不直接给出可迁移的参数手术。从修补走到 ROME/MEMIT，还要假设 MLP 近似线性关联记忆，并用秩一更新去改权重。中间多了一层建模假设。</span></p><p>度量饱和也是机制的一部分。若干净与损坏的 logit 差已经极大，修补会显得「处处有效」。应在难度适中的对照上做，或报告相对修复比例 \\((\\Delta_{\\mathrm{patch}}-\\Delta_{\\mathrm{corr}})/(\\Delta_{\\mathrm{clean}}-\\Delta_{\\mathrm{corr}})\\)。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>修补假设两次前向的位置对齐。变长提示、不同分词、插入干扰句，都会让「同一 \\(t\\)」失去意义。对生成任务，只修补提示最后一格，可能漏掉已经写进 KV 缓存的早期计算。对长链推理，关键信息可能分布在许多 token 上，单点修补会低估。</p><p>统计上，层 × 位置 × 头 的网格很大。应预注册扫描顺序，用保留集确认峰值，避免在同一批提示上既发现又验证。Zhang 与 Nanda 还警告：某些度量在数值上偏好深层，因为深层更靠近 logits；这不是机制更「集中」，只是杠杆更大。</p><p><span class="marginnote">不要把修补热力图当成电路图。热力图是充分性的扫描；电路还需要边、需要反向修补、需要在分布外提示上重复。IOI 之所以成立，是因为后续一串头级路径修补与行为预测都对上了，而不是因为某一层颜色深。</span></p>',26)),(t(),h(s,null,{default:i(()=>[p(n,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%B9%B2%E5%87%80%E5%89%8D%E5%90%91%20x_clean%22%5D%20--%3E%20H%5B%22%E6%BF%80%E6%B4%BB%20h%22%5D%0A%20%20D%5B%22%E6%8D%9F%E5%9D%8F%E5%89%8D%E5%90%91%20x_corr%22%5D%20--%3E%20Y%5B%22%E9%94%99%E8%AF%AF%E8%BE%93%E5%87%BA%22%5D%0A%20%20H%20--%3E%20P%5B%22%E5%9C%A8%E6%8C%87%E5%AE%9A%E5%B1%82%2F%E4%BD%8D%E7%BD%AE%E5%86%99%E5%85%A5%22%5D%0A%20%20D%20--%3E%20P%0A%20%20P%20--%3E%20R%5B%22%E8%BE%93%E5%87%BA%E6%98%AF%E5%90%A6%E8%A2%AB%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20R%20--%3E%20Suff%5B%22%E5%85%85%E5%88%86%E6%80%A7%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>激活修补用干净运行的激活替换损坏运行的对应激活，检验该位点是否因果介导目标行为。</li><li>必须成对看充分性（贴入能否修好）与必要性（贴入损坏能否弄坏）。</li><li>损坏构造、度量与归一化会改变定位；应报告修复曲线而非单一峰值。</li><li>粗修补定层与 token，细修补定头与边；路径修补才能谈电路的边。</li><li>修补定位的是激活位点，权重编辑还需要额外的记忆模型假设。</li><li>出处：Meng et al., NeurIPS 2022；Wang et al., <em>Interpretability in the Wild</em>（IOI）, ICLR 2023；Zhang &amp; Nanda, ICLR 2024。</li></ul>',2))])}const B=l(m,[["render",d]]);export{f as __pageData,B as default};
